WITH ranked AS (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY quantity ASC NULLS FIRST) AS rank_in_group FROM inventory QUALIFY rank_in_group = 1), enriched AS (SELECT a.*, p.category, p.cost, p.brand FROM ranked a LEFT JOIN products p ON a.product_id = p.id), remaining_keys AS (SELECT id, product_id FROM enriched EXCEPT ALL SELECT id, product_id FROM inventory WHERE product_id IN (4, 5, 9)), verified AS (SELECT s.* FROM enriched s INNER JOIN remaining_keys k ON s.id = k.id AND s.product_id = k.product_id), filtered AS (SELECT id, store_id, product_id, quantity, last_restock, rank_in_group, category, brand, DATE_TRUNC('month', last_restock) AS last_restock_period FROM verified WHERE last_restock >= DATE '2023-08-23' AND brand IS NOT NULL AND quantity < 141) SELECT store_id, product_id, ROUND(SUM(quantity) / NULLIF(COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END), 0), 2) AS quantity_per_umbrella, SUM(CASE WHEN category = 'Books' THEN quantity ELSE 0 END) AS books_quantity, AVG(quantity) AS avg_quantity, (UNIX_TIMESTAMP(MAX(last_restock_period)) - UNIX_TIMESTAMP(MIN(last_restock_period))) / 60 AS span_minutes, RANK() OVER (PARTITION BY store_id ORDER BY AVG(quantity) DESC) AS avg_quantity_rank FROM filtered GROUP BY store_id, product_id ORDER BY store_id DESC
